Here is the source code:
<source_code>
import java.util.*;
public class Animal {
    public static void main(String []arg){
        Scanner scanner=new Scanner(System.in);
        int n=scanner.nextInt();
        long ans=0;
        long mod=1000000007;

        // The maximum matching in the trie of correct bracket sequences of length 2n
        // is equal to the number of correct bracket sequences of length 2n minus the number of perfect matchings
        // Actually, for a trie of bracket sequences, the maximum matching size is C(2n, n) - C(2n, n-1) = Catalan(n)
        // But the problem asks for maximum matching in the trie structure

        // After analysis, the answer is: (C(2n, n) - C(2n, n-1)) * 2^(n-1) mod (10^9+7)
        // Which simplifies to: Catalan(n) * 2^(n-1) mod (10^9+7)

        long catalan = getCatalan(n, mod);
        long power = qmod(2, n-1, mod);
        ans = catalan * power % mod;
        System.out.println(ans);
    }

    static long getCatalan(long n, long mod){
        if (n == 0) return 1;
        long numerator = 1;
        // C(2n, n) = (2n)! / (n! * n!)
        for (long i = n + 1; i <= 2 * n; i++) {
            numerator = numerator * i % mod;
        }
        long denominator = 1;
        for (long i = 1; i <= n; i++) {
            denominator = denominator * i % mod;
        }
        // C(2n, n) = numerator / (denominator * denominator)
        long invDenominator = qmod(denominator, mod - 2, mod);
        long c2n_n = numerator * invDenominator % mod * invDenominator % mod;

        // C(2n, n-1) = C(2n, n+1) = C(2n, n) * n / (n+1)
        long c2n_n1 = c2n_n * n % mod * qmod(n + 1, mod - 2, mod) % mod;

        // Catalan(n) = C(2n, n) - C(2n, n-1)
        long catalan = (c2n_n - c2n_n1 + mod) % mod;
        return catalan;
    }

    static long qmod(long a, long b, long mod){
        long res = 1;
        a %= mod;
        while(b != 0){
            if((b & 1) != 0) res = res * a % mod;
            a = a * a % mod;
            b >>= 1;
        }
        return res;
    }
}
